/** @author Jia Pan */

// fcl_distance: header-only extraction of FCL 0.7.0 include/fcl/geometry/shape/triangle_p-inl.h



namespace fcl
{

//==============================================================================
//==============================================================================
template <typename S>
TriangleP<S>::TriangleP(
    const Vector3<S>& a,
    const Vector3<S>& b,
    const Vector3<S>& c)
  : ShapeBase<S>(), a(a), b(b), c(c)
{
  // Do nothing
}

//==============================================================================
template <typename S>
void TriangleP<S>::computeLocalAABB()
{
  this->aabb_local = AABB<S>(a, b, c);

  this->aabb_center = this->aabb_local.center();
  this->aabb_radius = (this->aabb_local.min_ - this->aabb_center).norm();
}

//==============================================================================
template <typename S>
NODE_TYPE TriangleP<S>::getNodeType() const
{
  return GEOM_TRIANGLE;
}

//==============================================================================
template <typename S>
std::vector<Vector3<S>> TriangleP<S>::getBoundVertices(
    const Transform3<S>& tf) const
{
  std::vector<Vector3<S>> result(3);
  result[0] = tf * a;
  result[1] = tf * b;
  result[2] = tf * c;

  return result;
}

} // namespace fcl

